//! Pure-Rust, dependency-free port of the pieces of the C++ program
//! `tests/test4.cpp` that lived outside `main`: the `mapbox::earcut`
//! polygon triangulation, the polygon the test builds, and the C `atoi`
//! argument parsing.
//!
//! ```
//! use earcut_test4::{earcut::earcut, polygon::overlapping_squares};
//!
//! let indices = earcut(&overlapping_squares(1));
//! assert_eq!(indices, vec![2, 3, 0, 0, 1, 2]);
//! ```

pub mod cli;
pub mod earcut;
pub mod polygon;

/// Render a triangle index list the way `test4.cpp` does: every index followed
/// by a single space, with no trailing newline.
pub fn format_indices(indices: &[u32]) -> String {
    let mut out = String::new();
    for idx in indices {
        out.push_str(&idx.to_string());
        out.push(' ');
    }
    out
}
//! Command line helpers.
//!
//! `test4.cpp` reads its single optional argument with `std::atoi`, which has
//! semantics no `std` Rust parser reproduces: leading whitespace is skipped, an
//! optional sign is accepted, parsing stops at the first non-digit, a string
//! with no digits at all yields `0`, and out-of-range values are truncated to
//! `int` rather than reported as an error.

/// Reimplementation of C's `atoi` as glibc provides it: `(int) strtol(s, NULL, 10)`.
///
/// `strtol` saturates at `LONG_MIN` / `LONG_MAX` (64-bit on this platform) and
/// the result is then truncated to 32 bits, so e.g. `"99999999999999999999"`
/// becomes `-1` just as it does in C.
pub fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0usize;

    // isspace(): space, \t, \n, \v, \f, \r
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }

    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    // Accumulate in i64 (== C `long` here) with saturation, mirroring strtol.
    let mut acc: i64 = 0;
    let mut saturated = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let digit = i64::from(bytes[i] - b'0');
        if !saturated {
            match acc.checked_mul(10).and_then(|v| v.checked_add(digit)) {
                Some(v) => acc = v,
                None => saturated = true,
            }
        }
        i += 1;
    }

    let value = if saturated {
        if negative {
            i64::MIN
        } else {
            i64::MAX
        }
    } else if negative {
        -acc
    } else {
        acc
    };

    value as i32
}

#[cfg(test)]
mod tests {
    use super::atoi;

    #[test]
    fn matches_c_atoi() {
        assert_eq!(atoi(""), 0);
        assert_eq!(atoi("abc"), 0);
        assert_eq!(atoi("7abc"), 7);
        assert_eq!(atoi(" 9"), 9);
        assert_eq!(atoi("+6"), 6);
        assert_eq!(atoi("-3"), -3);
        assert_eq!(atoi("0"), 0);
        assert_eq!(atoi("  \t-12x34"), -12);
        assert_eq!(atoi("2147483648"), -2147483648);
        assert_eq!(atoi("99999999999999999999"), -1);
    }
}
//! The polygon `test4.cpp` builds.
//!
//! `n` rings, each an axis-aligned square of side `n` whose lower-left corner
//! sits at `(2i, 2i)`. Because the offset step (2) is smaller than the side
//! (`n`) for all `n > 2`, the rings overlap heavily instead of nesting, so
//! earcut sees a badly self-intersecting polygon and exercises its fallback
//! paths. Ring 0 is treated as the outer contour and rings 1.. as holes.

/// Build the polygon for a given `n`. A non-positive `n` yields no rings,
/// exactly as the C++ `for (int i = 0; i < n; i++)` loop does.
pub fn overlapping_squares(n: i32) -> Vec<Vec<[f64; 2]>> {
    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();

    let side = f64::from(n);
    let mut i: i32 = 0;
    while i < n {
        // `double offset = i * 2;` — int multiply, then widen.
        let offset = f64::from(i.wrapping_mul(2));
        polygon.push(vec![
            [offset, offset],
            [offset + side, offset],
            [offset + side, offset + side],
            [offset, offset + side],
        ]);
        i += 1;
    }

    polygon
}

#[cfg(test)]
mod tests {
    use super::overlapping_squares;

    #[test]
    fn shape_matches_the_cpp_loop() {
        assert!(overlapping_squares(0).is_empty());
        assert!(overlapping_squares(-3).is_empty());

        let p = overlapping_squares(3);
        assert_eq!(p.len(), 3);
        assert!(p.iter().all(|ring| ring.len() == 4));
        assert_eq!(p[0], [[0.0, 0.0], [3.0, 0.0], [3.0, 3.0], [0.0, 3.0]]);
        assert_eq!(p[2], [[4.0, 4.0], [7.0, 4.0], [7.0, 7.0], [4.0, 7.0]]);
    }
}

#include <iostream>
#include <vector>
#include <array>
#include "../earcut.hpp"

int main(int argc, char* argv[]) {
    int n = 4;
    if (argc > 1) {
        n = std::atoi(argv[1]);
    }

    std::vector<std::vector<std::array<double, 2>>> polygon;

    for (int i = 0; i < n; i++) {
        std::vector<std::array<double, 2>> ring;
        double offset = i * 2;
        ring.push_back({offset, offset});
        ring.push_back({offset + n, offset});
        ring.push_back({offset + n, offset + n});
        ring.push_back({offset, offset + n});
        polygon.push_back(ring);
    }

    auto indices = mapbox::earcut<uint32_t>(polygon);

    for (auto idx : indices) {
        std::cout << idx << " ";
    }
    return 0;
}


