//! A from-scratch Rust port of the `mapbox::earcut` polygon triangulator.
//!
//! Input is a polygon given as a list of rings: ring 0 is the outer contour and
//! every following ring is a hole. Vertex indices in the returned triangle list
//! refer to the flattened concatenation of all rings, so ring 1's first vertex
//! has index `ring0.len()`.
//!
//! The algorithm is ear clipping with three escalating fallbacks for input that
//! is not a simple polygon: filtering degenerate points, curing local
//! self-intersections, and finally splitting the ring along a valid diagonal.
//! Because that fallback ladder makes the output order depend on fine details
//! of the traversal, this port follows the reference control flow statement for
//! statement rather than reformulating it.

pub mod geom;
pub mod node;
mod holes;
mod zorder;

use self::geom::point_in_triangle;
pub use self::node::{Node, NIL};

/// Triangulate a polygon, returning a flat list of triangle vertex indices.
///
/// Equivalent to `mapbox::earcut<uint32_t>(polygon)`.
pub fn earcut(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut state = Earcut::new();
    state.run(polygon);
    state.indices
}

/// Triangulation state: the node arena plus the z-order hash parameters.
pub struct Earcut {
    /// Flat triangle list, three vertex indices per triangle.
    pub indices: Vec<u32>,
    /// Number of vertices consumed by rings linked so far.
    vertices: usize,
    /// Arena backing every [`Node`]; handles into it are never invalidated.
    nodes: Vec<Node>,

    hashing: bool,
    min_x: f64,
    max_x: f64,
    min_y: f64,
    max_y: f64,
    inv_size: f64,
}

impl Default for Earcut {
    fn default() -> Self {
        Self::new()
    }
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            indices: Vec::new(),
            vertices: 0,
            nodes: Vec::new(),
            hashing: false,
            min_x: 0.0,
            max_x: 0.0,
            min_y: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    /// `operator()(points)` — the top level driver.
    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        self.indices.clear();
        self.vertices = 0;

        if points.is_empty() {
            return;
        }

        // Decide whether the shape is complex enough to be worth hashing, and
        // size the arena while we are walking the rings. The loop stops early
        // once the threshold goes negative, so `len` is only a lower bound.
        let mut threshold: i32 = 80;
        let mut len: usize = 0;
        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i32;
            len += points[i].len();
            i += 1;
        }

        self.nodes.reserve(len * 3 / 2);
        self.indices.reserve(len + points[0].len());

        let mut outer_node = self.linked_list(&points[0], true);
        if outer_node == NIL || self.prev(outer_node) == self.next(outer_node) {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // If the shape is not too simple we use a z-order curve hash later, so
        // calculate the polygon bbox now.
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.next(outer_node);
            self.min_x = self.x(outer_node);
            self.max_x = self.min_x;
            self.min_y = self.y(outer_node);
            self.max_y = self.min_y;
            loop {
                let (x, y) = (self.x(p), self.y(p));
                self.min_x = f64::min(self.min_x, x);
                self.min_y = f64::min(self.min_y, y);
                self.max_x = f64::max(self.max_x, x);
                self.max_y = f64::max(self.max_y, y);
                p = self.next(p);
                if p == outer_node {
                    break;
                }
            }

            // min_x, min_y and inv_size transform coords into the integer range
            // the z-order calculation wants.
            self.inv_size = f64::max(self.max_x - self.min_x, self.max_y - self.min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);

        self.nodes.clear();
    }

    /// `earcutLinked(ear, pass)` — main ear slicing loop.
    fn earcut_linked(&mut self, ear: usize, pass: i32) {
        if ear == NIL {
            return;
        }
        let mut ear = ear;

        // Interlink polygon nodes in z-order.
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // Iterate through ears, slicing them one by one.
        while self.prev(ear) != self.next(ear) {
            let prev = self.prev(ear);
            let next = self.next(ear);

            let found = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if found {
                // Cut off the triangle.
                self.indices.push(self.idx(prev));
                self.indices.push(self.idx(ear));
                self.indices.push(self.idx(next));

                self.remove_node(ear);

                // Skipping the next vertex leads to fewer sliver triangles.
                ear = self.next(next);
                stop = self.next(next);

                continue;
            }

            ear = next;

            // If we looped through the whole remaining polygon and can't find
            // any more ears, escalate.
            if ear == stop {
                if pass == 0 {
                    // Try filtering points and slicing again.
                    let filtered = self.filter_points(ear, NIL);
                    self.earcut_linked(filtered, 1);
                } else if pass == 1 {
                    // If that didn't work, try curing all small
                    // self-intersections locally.
                    let filtered = self.filter_points(ear, NIL);
                    let cured = self.cure_local_intersections(filtered);
                    self.earcut_linked(cured, 2);
                } else if pass == 2 {
                    // As a last resort, try splitting the remaining polygon
                    // into two.
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// `isEar(ear)` — linear scan ear test used when hashing is off.
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.prev(ear);
        let b = ear;
        let c = self.next(ear);

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // Now make sure we don't have other points inside the potential ear.
        let mut p = self.next(self.next(ear));

        while p != self.prev(ear) {
            if point_in_triangle(
                self.x(a),
                self.y(a),
                self.x(b),
                self.y(b),
                self.x(c),
                self.y(c),
                self.x(p),
                self.y(p),
            ) && self.area(self.prev(p), p, self.next(p)) >= 0.0
            {
                return false;
            }
            p = self.next(p);
        }

        true
    }

    /// `cureLocalIntersections(start)` — go through all polygon nodes and cure
    /// small local self-intersections.
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        if start == NIL {
            return NIL;
        }
        let mut start = start;
        let mut p = start;

        loop {
            let a = self.prev(p);
            let pn = self.next(p);
            let b = self.next(pn);

            // A self-intersection where edge (v[i-1], v[i]) intersects
            // (v[i+1], v[i+2]).
            if !self.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.idx(a));
                self.indices.push(self.idx(p));
                self.indices.push(self.idx(b));

                // Remove the two nodes involved. `remove_node` leaves `p`'s own
                // links intact, so `p.next` still names the second victim.
                self.remove_node(p);
                let p_next = self.next(p);
                self.remove_node(p_next);

                p = b;
                start = b;
            }

            p = self.next(p);
            if p == start {
                break;
            }
        }

        self.filter_points(p, NIL)
    }

    /// `splitEarcut(start)` — try splitting the polygon into two, then
    /// triangulate both halves independently.
    fn split_earcut(&mut self, start: usize) {
        // Look for a valid diagonal that divides the polygon in two.
        let mut a = start;
        loop {
            let mut b = self.next(self.next(a));
            while b != self.prev(a) {
                if self.idx(a) != self.idx(b) && self.is_valid_diagonal(a, b) {
                    // Split the polygon in two by the diagonal.
                    let mut c = self.split_polygon(a, b);

                    // Filter colinear points around the cuts.
                    let a_next = self.next(a);
                    let a = self.filter_points(a, a_next);
                    let c_next = self.next(c);
                    c = self.filter_points(c, c_next);

                    // Run earcut on each half.
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.next(b);
            }
            a = self.next(a);
            if a == start {
                break;
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::earcut;

    #[test]
    fn single_square() {
        let square = vec![vec![[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0]]];
        assert_eq!(earcut(&square), vec![2, 3, 0, 0, 1, 2]);
    }

    #[test]
    fn empty_polygon() {
        let empty: Vec<Vec<[f64; 2]>> = Vec::new();
        assert!(earcut(&empty).is_empty());
    }

    #[test]
    fn square_with_a_real_hole() {
        let polygon = vec![
            vec![[0.0, 0.0], [4.0, 0.0], [4.0, 4.0], [0.0, 4.0]],
            vec![[1.0, 1.0], [1.0, 3.0], [3.0, 3.0], [3.0, 1.0]],
        ];
        let indices = earcut(&polygon);
        // Eight vertices, one hole: 2 * 8 - 2 - 2 * 1 = 8 triangles.
        assert_eq!(indices.len(), 24);
        assert!(indices.iter().all(|&i| i < 8));
    }
}

//! The doubly linked ring node and the arena that owns it.
//!
//! The C++ implementation threads raw `Node*` pointers through every routine
//! and keeps them alive in an object pool that is only released at the very
//! end. Removed nodes therefore stay readable, and code such as
//! `removeNode(p); removeNode(p->next);` relies on that. We reproduce the
//! model exactly with a `Vec<Node>` arena and `usize` handles: a handle is
//! never invalidated, so identity comparisons (`p != ear.prev`) and reads of
//! unlinked nodes behave as they do in C++.

use super::Earcut;

/// Handle standing in for a null `Node*`.
pub const NIL: usize = usize::MAX;

#[derive(Clone, Debug)]
pub struct Node {
    /// Index of this vertex in the flattened input coordinate list.
    pub i: u32,
    pub x: f64,
    pub y: f64,

    /// Previous and next vertex nodes in the polygon ring.
    pub prev: usize,
    pub next: usize,

    /// Z-order curve value.
    pub z: i32,

    /// Previous and next nodes in z-order.
    pub prev_z: usize,
    pub next_z: usize,

    /// Whether this is a Steiner point.
    pub steiner: bool,
}

impl Node {
    pub fn new(i: u32, x: f64, y: f64) -> Self {
        Node {
            i,
            x,
            y,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        }
    }
}

impl Earcut {
    // -- field accessors -----------------------------------------------------
    //
    // Small copying getters keep every call site free of long-lived borrows,
    // which is what lets `&mut self` methods read and relink in one pass.

    #[inline]
    pub(crate) fn x(&self, p: usize) -> f64 {
        self.nodes[p].x
    }

    #[inline]
    pub(crate) fn y(&self, p: usize) -> f64 {
        self.nodes[p].y
    }

    #[inline]
    pub(crate) fn idx(&self, p: usize) -> u32 {
        self.nodes[p].i
    }

    #[inline]
    pub(crate) fn next(&self, p: usize) -> usize {
        self.nodes[p].next
    }

    #[inline]
    pub(crate) fn prev(&self, p: usize) -> usize {
        self.nodes[p].prev
    }

    // -- arena ---------------------------------------------------------------

    /// `nodes.construct(i, x, y)`
    pub(crate) fn construct(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node::new(i, x, y));
        self.nodes.len() - 1
    }

    /// `insertNode(i, point, last)` — create a node and splice it after `last`.
    pub(crate) fn insert_node(&mut self, i: usize, pt: [f64; 2], last: usize) -> usize {
        let p = self.construct(i as u32, pt[0], pt[1]);

        if last == NIL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let last_next = self.nodes[last].next;
            self.nodes[p].next = last_next;
            self.nodes[p].prev = last;
            self.nodes[last_next].prev = p;
            self.nodes[last].next = p;
        }

        p
    }

    /// `removeNode(p)` — unlink from both the ring and the z-order list.
    ///
    /// As in C++, `p`'s own `next`/`prev` fields are deliberately left intact.
    pub(crate) fn remove_node(&mut self, p: usize) {
        let (pn, pp) = (self.nodes[p].next, self.nodes[p].prev);
        self.nodes[pn].prev = pp;
        self.nodes[pp].next = pn;

        let (pz, nz) = (self.nodes[p].prev_z, self.nodes[p].next_z);
        if pz != NIL {
            self.nodes[pz].next_z = nz;
        }
        if nz != NIL {
            self.nodes[nz].prev_z = pz;
        }
    }

    /// `splitPolygon(a, b)` — link two ring vertices with a bridge, splitting
    /// the ring into two. Returns the second ring's entry node (`b2`).
    pub(crate) fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.construct(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let b2 = self.construct(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    /// `filterPoints(start, end)` — drop colinear or duplicate points.
    ///
    /// Pass [`NIL`] for `end` to get the C++ default argument (`end = start`).
    pub(crate) fn filter_points(&mut self, start: usize, end: usize) -> usize {
        if start == NIL {
            return NIL;
        }
        let mut end = if end == NIL { start } else { end };

        let mut p = start;
        loop {
            let mut again = false;

            let pn = self.nodes[p].next;
            let pp = self.nodes[p].prev;
            if !self.nodes[p].steiner && (self.equals(p, pn) || self.area(pp, p, pn) == 0.0) {
                self.remove_node(p);
                p = pp;
                end = pp;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = pn;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// `linkedList(points, clockwise)` — build a circular doubly linked list
    /// from one ring, in the requested winding order.
    pub(crate) fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
        let len = points.len();
        let mut last = NIL;

        // Calculate the original winding order of the ring.
        let mut sum = 0.0f64;
        if len > 0 {
            let mut j = len - 1;
            for i in 0..len {
                let p1 = points[i];
                let p2 = points[j];
                sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
                j = i;
            }
        }

        // Link points in the specified winding order.
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        } else {
            for i in (0..len).rev() {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        }

        if last != NIL {
            let last_next = self.nodes[last].next;
            if self.equals(last, last_next) {
                self.remove_node(last);
                last = last_next;
            }
        }

        self.vertices += len;

        last
    }
}
=====ZORDER
//! Z-order (Morton code) spatial hash.
//!
//! For polygons above a size threshold the ear test consults a z-order sorted
//! list instead of walking every remaining vertex. It is purely an
//! acceleration structure: the set of candidate points it visits is the same
//! set the linear scan would find inside the triangle, so both paths must
//! produce the same triangulation.

use super::geom::point_in_triangle;
use super::node::NIL;
use super::Earcut;

impl Earcut {
    /// `zOrder(x, y)` — interleave the bits of the two 15-bit coordinates.
    pub(crate) fn z_order(&self, x_: f64, y_: f64) -> i32 {
        // Coords are transformed into a non-negative 15-bit integer range.
        // The C++ `static_cast<int32_t>` truncates toward zero, which is what
        // Rust's `as` does for in-range values.
        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF_00FF;
        x = (x | (x << 4)) & 0x0F0F_0F0F;
        x = (x | (x << 2)) & 0x3333_3333;
        x = (x | (x << 1)) & 0x5555_5555;

        y = (y | (y << 8)) & 0x00FF_00FF;
        y = (y | (y << 4)) & 0x0F0F_0F0F;
        y = (y | (y << 2)) & 0x3333_3333;
        y = (y | (y << 1)) & 0x5555_5555;

        x | (y << 1)
    }

    /// `indexCurve(start)` — attach a z-order sorted linked list to the ring.
    pub(crate) fn index_curve(&mut self, start: usize) {
        debug_assert!(start != NIL);
        let mut p = start;

        loop {
            if self.nodes[p].z == 0 {
                self.nodes[p].z = self.z_order(self.x(p), self.y(p));
            }
            self.nodes[p].prev_z = self.nodes[p].prev;
            self.nodes[p].next_z = self.nodes[p].next;
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        // Break the circle so the merge sort sees a plain list.
        let pz = self.nodes[p].prev_z;
        self.nodes[pz].next_z = NIL;
        self.nodes[p].prev_z = NIL;

        self.sort_linked(p);
    }

    /// `sortLinked(list)` — bottom-up merge sort of the z-order linked list.
    ///
    /// The `p.z <= q.z` comparison makes the sort stable, so nodes with equal
    /// z keep their ring order. That ordering is observable in the output.
    pub(crate) fn sort_linked(&mut self, list: usize) -> usize {
        debug_assert!(list != NIL);
        let mut list = list;
        let mut in_size: i32 = 1;

        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut num_merges = 0;

            while p != NIL {
                num_merges += 1;
                let mut q = p;
                let mut p_size: i32 = 0;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NIL {
                        break;
                    }
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NIL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NIL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NIL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NIL;

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }

    /// `isEarHashed(ear)` — the z-order accelerated ear test.
    pub(crate) fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.prev(ear);
        let b = ear;
        let c = self.next(ear);

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.x(a), self.y(a));
        let (bx, by) = (self.x(b), self.y(b));
        let (cx, cy) = (self.x(c), self.y(c));

        // Triangle bbox; min & max are calculated like this for speed.
        let min_tx = f64::min(ax, f64::min(bx, cx));
        let min_ty = f64::min(ay, f64::min(by, cy));
        let max_tx = f64::max(ax, f64::max(bx, cx));
        let max_ty = f64::max(ay, f64::max(by, cy));

        // Z-order range for the current triangle bbox.
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        let mut p = self.nodes[ear].prev_z;
        let mut n = self.nodes[ear].next_z;

        // Look for points inside the triangle in both directions.
        while p != NIL && self.nodes[p].z >= min_z && n != NIL && self.nodes[n].z <= max_z {
            if self.x(p) >= min_tx
                && self.x(p) <= max_tx
                && self.y(p) >= min_ty
                && self.y(p) <= max_ty
                && p != a
                && p != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(p), self.y(p))
                && self.area(self.prev(p), p, self.next(p)) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;

            if self.x(n) >= min_tx
                && self.x(n) <= max_tx
                && self.y(n) >= min_ty
                && self.y(n) <= max_ty
                && n != a
                && n != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(n), self.y(n))
                && self.area(self.prev(n), n, self.next(n)) >= 0.0
            {
                return false;
            }
            n = self.nodes[n].next_z;
        }

        // Look for remaining points in decreasing z-order.
        while p != NIL && self.nodes[p].z >= min_z {
            if p != a
                && p != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(p), self.y(p))
                && self.area(self.prev(p), p, self.next(p)) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        // Look for remaining points in increasing z-order.
        while n != NIL && self.nodes[n].z <= max_z {
            if n != a
                && n != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(n), self.y(n))
                && self.area(self.prev(n), n, self.next(n)) >= 0.0
            {
                return false;
            }
            n = self.nodes[n].next_z;
        }

        true
    }
}

//! Geometric predicates.
//!
//! Every expression here is kept in the exact algebraic form the C++ uses.
//! Rearranging them (even into a mathematically equivalent shape) changes
//! floating point rounding and can flip a `>= 0` test on a degenerate input,
//! which in turn changes which ear is clipped and therefore the output order.

use super::Earcut;

/// `area(p, q, r)` — twice the signed area of the triangle, negative for a
/// counter-clockwise turn.
#[inline]
pub fn area_xy(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> f64 {
    (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
}

/// `pointInTriangle(...)` — boundary counts as inside (all tests are `>= 0`).
#[inline]
#[allow(clippy::too_many_arguments)]
pub fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

/// `sign(val)` — `(0 < val) - (val < 0)`.
#[inline]
pub fn sign(val: f64) -> i32 {
    i32::from(0.0 < val) - i32::from(val < 0.0)
}

impl Earcut {
    #[inline]
    pub(crate) fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        area_xy(
            self.x(p),
            self.y(p),
            self.x(q),
            self.y(q),
            self.x(r),
            self.y(r),
        )
    }

    /// `equals(p1, p2)` — exact coordinate equality.
    #[inline]
    pub(crate) fn equals(&self, p1: usize, p2: usize) -> bool {
        self.x(p1) == self.x(p2) && self.y(p1) == self.y(p2)
    }

    /// `onSegment(p, q, r)` — `q` lies inside the bounding box of `pr`.
    #[inline]
    pub(crate) fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
        self.x(q) <= f64::max(self.x(p), self.x(r))
            && self.x(q) >= f64::min(self.x(p), self.x(r))
            && self.y(q) <= f64::max(self.y(p), self.y(r))
            && self.y(q) >= f64::min(self.y(p), self.y(r))
    }

    /// `intersects(p1, q1, p2, q2)` — do the two segments properly or
    /// colinearly intersect?
    pub(crate) fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }

        if o1 == 0 && self.on_segment(p1, p2, q1) {
            return true; // p1, q1 and p2 are colinear and p2 lies on p1q1
        }
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            return true; // p1, q1 and q2 are colinear and q2 lies on p1q1
        }
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            return true; // p2, q2 and p1 are colinear and p1 lies on p2q2
        }
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            return true; // p2, q2 and q1 are colinear and q1 lies on p2q2
        }

        false
    }

    /// `intersectsPolygon(a, b)` — does the diagonal `ab` cross any ring edge?
    pub(crate) fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.next(p);
            if self.idx(p) != self.idx(a)
                && self.idx(pn) != self.idx(a)
                && self.idx(p) != self.idx(b)
                && self.idx(pn) != self.idx(b)
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }

        false
    }

    /// `locallyInside(a, b)` — is the segment `ab` inside the polygon in the
    /// immediate neighbourhood of `a`?
    pub(crate) fn locally_inside(&self, a: usize, b: usize) -> bool {
        let ap = self.prev(a);
        let an = self.next(a);
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    /// `middleInside(a, b)` — is the midpoint of `ab` inside the polygon?
    pub(crate) fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.x(a) + self.x(b)) / 2.0;
        let py = (self.y(a) + self.y(b)) / 2.0;
        loop {
            let pn = self.next(p);
            if ((self.y(p) > py) != (self.y(pn) > py))
                && self.y(pn) != self.y(p)
                && (px
                    < (self.x(pn) - self.x(p)) * (py - self.y(p)) / (self.y(pn) - self.y(p))
                        + self.x(p))
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }

        inside
    }

    /// `isValidDiagonal(a, b)` — can the polygon be split along `ab`?
    pub(crate) fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let an = self.next(a);
        let ap = self.prev(a);
        let bp = self.prev(b);
        let bn = self.next(b);

        self.idx(an) != self.idx(b)
            && self.idx(ap) != self.idx(b)
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)   // locally visible
                // does not create opposite-facing sectors
                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
                // special zero-length case
                || (self.equals(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(bp, b, bn) > 0.0))
    }

    /// `sectorContainsSector(m, p)` — whether the sector at `m` contains the
    /// sector at `p`.
    pub(crate) fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(self.prev(m), m, self.prev(p)) < 0.0
            && self.area(self.next(p), m, self.next(m)) < 0.0
    }
}
=====HOLES
//! Hole elimination: each inner ring is bridged into the outer ring so the
//! whole polygon becomes a single (self-touching) ring the ear clipper can eat.

use super::node::NIL;
use super::Earcut;
use super::geom::point_in_triangle;

impl Earcut {
    /// `eliminateHoles(points, outerNode)`
    pub(crate) fn eliminate_holes(
        &mut self,
        points: &[Vec<[f64; 2]>],
        mut outer_node: usize,
    ) -> usize {
        let len = points.len();

        let mut queue: Vec<usize> = Vec::new();
        for ring in points.iter().take(len).skip(1) {
            let list = self.linked_list(ring, false);
            if list != NIL {
                if self.next(list) == list {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }

        // `std::sort` by ascending x. The C++ comparator is a strict `a->x <
        // b->x`; every leftmost node in this program has a distinct x, so the
        // (unspecified) ordering `std::sort` gives equal keys never comes up
        // and a stable sort is an exact stand-in.
        let xs: Vec<f64> = queue.iter().map(|&n| self.x(n)).collect();
        let mut order: Vec<usize> = (0..queue.len()).collect();
        order.sort_by(|&a, &b| xs[a].partial_cmp(&xs[b]).unwrap());
        let queue: Vec<usize> = order.into_iter().map(|i| queue[i]).collect();

        // Process holes from left to right.
        for &hole in &queue {
            outer_node = self.eliminate_hole(hole, outer_node);
        }

        outer_node
    }

    /// `eliminateHole(hole, outerNode)` — find a bridge and link the hole in.
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        // Find a bridge between vertices that connects the hole with an outer
        // ring, and link it.
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NIL {
            return outer_node;
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        // Filter colinear points around the cuts.
        let br_next = self.next(bridge_reverse);
        self.filter_points(bridge_reverse, br_next);

        // Check if the input node was removed by the filtering.
        let b_next = self.next(bridge);
        self.filter_points(bridge, b_next)
    }

    /// `findHoleBridge(hole, outerNode)` — David Eberly's algorithm for finding
    /// a bridge between a hole and an outer ring.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.x(hole);
        let hy = self.y(hole);
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        // Find a segment intersected by a ray from the hole's leftmost vertex
        // going left; the segment endpoint with the lesser x is the potential
        // connection vertex.
        loop {
            let pn = self.next(p);
            if hy <= self.y(p) && hy >= self.y(pn) && self.y(pn) != self.y(p) {
                let x = self.x(p)
                    + (hy - self.y(p)) * (self.x(pn) - self.x(p)) / (self.y(pn) - self.y(p));
                if x <= hx && x > qx {
                    qx = x;
                    m = if self.x(p) < self.x(pn) { p } else { pn };
                    if x == hx {
                        // Hole touches the outer segment; pick the leftmost
                        // endpoint.
                        return m;
                    }
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        // Look for points strictly inside the triangle of the hole vertex, the
        // segment intersection and the endpoint. If there are none we have a
        // valid connection; otherwise choose the vertex forming the minimum
        // angle with the ray.
        let stop = m;
        let mut tan_min = f64::INFINITY;
        let mx = self.x(m);
        let my = self.y(m);

        p = m;
        loop {
            let px = self.x(p);
            let py = self.y(p);
            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px); // tangential

                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.x(m) || self.sector_contains_sector(m, p))))
                {
                    m = p;
                    tan_min = tan;
                }
            }

            p = self.next(p);
            if p == stop {
                break;
            }
        }

        m
    }

    /// `getLeftmost(start)` — smallest x, ties broken by smallest y.
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.x(p) < self.x(leftmost)
                || (self.x(p) == self.x(leftmost) && self.y(p) < self.y(leftmost))
            {
                leftmost = p;
            }
            p = self.next(p);
            if p == start {
                break;
            }
        }

        leftmost
    }
}

